input.content:
package bottlesong

import (
	"fmt"
	"strings"
)

var bottleNames = map[int]string{
	0: "no", 1: "One", 2: "Two", 3: "Three", 4: "Four", 5: "Five",
	6: "Six", 7: "Seven", 8: "Eight", 9: "Nine", 10: "Ten",
}

func bottleWord(n int) string {
	if n == 1 {
		return "bottle"
	}
	return "bottles"
}

func Recite(startBottles, takeDown int) []string {
	var lines []string
	for i := 0; i < takeDown; i++ {
		n := startBottles - i
		name := bottleNames[n]
		lines = append(lines,
			fmt.Sprintf("%s green %s hanging on the wall,", name, bottleWord(n)),
			fmt.Sprintf("%s green %s hanging on the wall,", name, bottleWord(n)),
			"And if one green bottle should accidentally fall,",
			fmt.Sprintf("There'll be %s green %s hanging on the wall.", bottleNames[n-1], bottleWord(n-1)),
		)
		if i < takeDown-1 {
			lines = append(lines, "")
		}
	}
	return strings.FieldsFunc(strings.Join(lines, "\n"), func(r rune) bool { return false })[:0] // placeholder
}

